<template>
  <div class="container-fluid">
    <div class="row">
      <h3>Play<strong class="text-primary">Film</strong></h3>
      <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
          <li class="breadcrumb-item"><a href="/">Home</a></li>
          <li class="breadcrumb-item active" aria-current="page">
            {{ detailFilm.judul }}
          </li>
        </ol>
      </nav>
    </div>
    <div class="row justify-content-center mt-2">
      <div class="col-md-12">
        <div class="card rounded-4 p-3 border-0 shadow-lg">
          <div class="card-body">
            <div class="row">
              <div class="col-md-8">
                <video
                  v-if="detailFilm.source"
                  width="100%"
                  controls
                  :src="'assets/video/' + detailFilm.source"
                  class="rounded-3 ratio ratio-16x9"
                />
                <p v-else class="text-danger">Video belum tersedia</p>
              </div>
              <div class="col-md-4">
                <h3 class="card-text">
                  {{ detailFilm.judul }}
                </h3>
                <div class="my-3 text-secondary">
                  <span class="me-2"
                    ><i class="bi bi-display"></i> {{ detailFilm.display }}p
                  </span>
                  |
                  <span class="me-2">
                    <i class="bi bi-film"></i> {{ detailFilm.genre }}</span
                  >
                  |
                  <span class="me-2">
                    <i class="bi bi-calendar-event"></i>
                    {{ detailFilm.tahun }}</span
                  >
                  |
                  <span class="me-2">
                    <i class="bi bi-star"></i> {{ detailFilm.reting }}</span
                  >
                  |
                  <span class="me-2">
                    <i class="bi bi-eye"></i> {{ detailFilm.view }}</span
                  >
                  |
                  <router-link
                    :to="'/play/' + detailFilm.id"
                    class="text-link me-2"
                  >
                    <i class="bi bi-download"></i> Download</router-link
                  >
                </div>

                <div class="komentar shadow">
                  <p
                    class="chat shadow-sm show-komentar"
                    v-for="komen in komentar"
                    :key="komen.id"
                  >
                    <span class="fw-bold text-secondary">
                      <i class="bi bi-"></i> {{ komen.username }}
                    </span>
                    <span class="text-secondary float-end ts-13"
                      ><i class="bi bi-calendar"></i>
                      {{ komen.uploadted }} </span
                    ><br />
                    {{ komen.komentar }}
                  </p>
                  <div id="no-komen"></div>
                </div>
                <form action="" class="input-komentar">
                  <div class="input-group mb-3 mt-2">
                    <input
                      type="text"
                      class="form-control"
                      placeholder="Komentar....."
                      autocomplete="off"
                      id="komentar"
                    />
                    <button
                      class="btn btn-outline-primary"
                      type="button"
                      id="komentar"
                    >
                      <i class="bi bi-send"></i>
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import axios from "axios";
import sjcl from "sjcl";

export default {
  name: "PlayView",
  data() {
    return {
      detailFilm: {},
      komentar: [],
    };
  },
  methods: {
    setDetailFilm(data) {
      this.detailFilm = data;
    },
    setKomentar(data) {
      if (data && data.length > 0) {
        this.komentar = data;
      } else {
        const el = document.querySelector(".show-komentar");
        if (el) el.remove();
        const noKomen = document.querySelector("#no-komen");
        if (noKomen) {
          noKomen.innerHTML = `
            <p class="text-center fw-bold text-secondary no-komen">
              Jadilah Yang Pertama Komentar
            </p>
          `;
        }
      }
    },
    Dekripsi(id) {
      const key = "12345678";
      return sjcl.decrypt(key, id);
    },
  },
  mounted() {
    const encryptedId = this.$route.params.id;
    const decryptedId = this.Dekripsi(encryptedId);

    axios
      .get("http://localhost:3000/hero-films?id=" + decryptedId)
      .then((response) => this.setDetailFilm(response.data[0]))
      .catch((error) => console.error("Error fetching data:", error));

    axios
      .get("http://localhost:3000/komentar?id=" + decryptedId)
      .then((response) => this.setKomentar(response.data))
      .catch((error) => console.error("Error fetching komentar:", error));
  },
};
</script>
