<template>
  <div class="container-fluid mt-4">
    <div class="row mb-3">
      <div class="col-md-12">
        <div class="row">
          <div class="col-6">
            <label for="Cari-Films">Cari Films Kesukaanmu</label>
            <div class="input-group mb-3 mt-2">
              <input
                v-model="cari"
                type="text"
                class="form-control"
                placeholder="Harry Potter"
                autocomplete="off"
                autofocus
                style="max-width: 400px"
                id="Cari-Films"
                @input="cariFilms"
              />
              <button
                class="btn btn-outline-primary"
                type="button"
                @click="cariFilms"
              >
                <i class="bi bi-search"></i>
              </button>
            </div>
          </div>
          <div class="col-6 text-end">
            <h3>Ter<strong class="text-primary">Favorit</strong></h3>
            <p class="text-secondary">Film yang sedang banyak ditonton</p>
          </div>
        </div>
      </div>
    </div>

    <div class="row justify-content-center">
      <div class="col-6 col-md-2 mb-3" v-for="film in films" :key="film.id">
        <div class="card border-0 shadow">
          <div class="card-body">
            <img class="w-100" :src="'assets/img/' + film.gambar" alt="film" />
            <p class="mt-2">{{ film.judul }}</p>
            <div style="font-size: 12px">
              <span class="badge text-bg-danger me-1"
                >Genre {{ film.genre }}</span
              >
              <span class="badge text-bg-warning me-1"
                >Rating {{ film.reting }}</span
              >
              <span class="badge text-bg-success me-1"
                >View {{ film.view }}</span
              >
              <span class="badge text-bg-primary me-1"
                >Tahun {{ film.tahun }}</span
              >
            </div>
            <router-link
              :to="'/play/' + encodeURIComponent(hastId(film.id))"
              class="mt-2 w-100 btn btn-primary btn-sm"
            >
              Play Film
            </router-link>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import axios from "axios";
import sjcl from "sjcl";

export default {
  name: "HeroComponent",
  data() {
    return {
      films: [],
      cari: "",
      debounceTimer: null,
    };
  },
  methods: {
    setFilms(data) {
      this.films = data;
    },
    cariFilms() {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = setTimeout(() => {
        const url = this.cari
          ? `http://localhost:3000/hero-films?judul=${encodeURIComponent(
              this.cari
            )}`
          : "http://localhost:3000/hero-films";
        axios
          .get(url)
          .then((response) => this.setFilms(response.data))
          .catch((error) => console.error(error));
      }, 300);
    },
    hastId(id) {
      const key = "12345678";
      return sjcl.encrypt(key, id.toString());
    },
  },
  mounted() {
    this.cariFilms();
  },
};
</script>
